
import type { DeliveryEligibilityMismatchInput } from './DeliveryEligibilityMismatchInput.js';

export type DeliveryMerchantDiagnosticInput = { /** Stable reason the method did not produce an option. - `eligibility_no_match`: The configured eligibility expression excluded the method. - `method_unavailable`: The method was unavailable for this evaluation. - `input_required`: The buyer or caller must provide more information to evaluate the method. - `checkout_context_required`: A checkout session is required to evaluate the method. - `preview_unsupported`: The method cannot be evaluated without a checkout session. - `dependency_failure`: Flint could not check whether the method is available. */ "code": "eligibility_no_match" | "method_unavailable" | "input_required" | "checkout_context_required" | "preview_unsupported" | "dependency_failure"; "delivery_method_id"?: string; "delivery_method_revision_id"?: string; "diagnostic_id": string; /** Configured eligibility predicates that conclusively rejected the method. Present only for eligibility_no_match. */ "eligibility_mismatches"?: Array<DeliveryEligibilityMismatchInput>; /** RFC3339 timestamp. Format: date-time. */ "occurred_at": string | globalThis.Date; "outcome": "unavailable" | "input_required" | "cannot_calculate" | "requires_checkout_context" | "unsupported_in_preview"; "recommended_action": "review_configuration" | "provide_input" | "create_checkout" | "retry"; "retryable": boolean; "scope": "method"; "summary": string; };
